package com.lendup.reservas.infrastructure.client;
import com.lendup.reservas.application.exception.DependencyUnavailableException; import com.lendup.reservas.application.port.out.IdentidadPort; import com.lendup.reservas.config.IntegrationProperties; import java.util.*; import org.springframework.stereotype.Component; import org.springframework.web.client.RestClient;
@Component public class IdentidadRestAdapter implements IdentidadPort { private final IntegrationProperties.Identity config; private final RestClient client; public IdentidadRestAdapter(IntegrationProperties p){config=p.identity();client=config.baseUrl().isBlank()?null:RestClientFactory.create(config.baseUrl(),config.connectTimeoutMs(),config.readTimeoutMs());}
  public UUID resolverUsuarioId(String firebaseUid){requireConfigured(config.firebaseUserUriTemplate(),"resolución de identidad");try{@SuppressWarnings("unchecked") Map<String,Object> row=client.get().uri(config.firebaseUserUriTemplate(),firebaseUid).header("Authorization","Bearer "+config.serviceToken()).retrieve().body(Map.class);if(row==null||row.get("usuario_id")==null)throw new DependencyUnavailableException("Identidad no vinculó el token a un usuario interno");return UUID.fromString(row.get("usuario_id").toString());}catch(DependencyUnavailableException e){throw e;}catch(Exception e){throw new DependencyUnavailableException("Identidad no disponible",e);}}
  public String obtenerTelefonoAutorizado(UUID user,UUID reservation){requireConfigured(config.authorizedContactUriTemplate(),"contacto autorizado");try{@SuppressWarnings("unchecked") Map<String,Object> row=client.get().uri(config.authorizedContactUriTemplate(),user,reservation).header("Authorization","Bearer "+config.serviceToken()).retrieve().body(Map.class);if(row==null||row.get("telefono")==null)throw new DependencyUnavailableException("Identidad no entregó teléfono autorizado");return row.get("telefono").toString();}catch(DependencyUnavailableException e){throw e;}catch(Exception e){throw new DependencyUnavailableException("Identidad no disponible",e);}}
  private void requireConfigured(String uriTemplate,String operation){if(client==null||config.serviceToken().isBlank()||uriTemplate.isBlank())throw new DependencyUnavailableException("Integración de "+operation+" con Identidad no configurada");}
}
